import { useEffect, useState, useRef } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { createSuscripcion } from '../../services/suscripcionService';
import { useAuth } from '../../services/AuthContext';

export function PagoExitoso() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const hasProcessed = useRef(false);

  useEffect(() => {
    const processPayment = async () => {
      // Evitar la doble ejecución de useEffect en React Strict Mode
      if (hasProcessed.current) return;
      hasProcessed.current = true;

      const sessionId = searchParams.get('session_id');
      const plan = searchParams.get('plan') as 'BASICA' | 'PREMIUM' | 'VIP';
      const usuarioIdStr = searchParams.get('usuarioId');
      const usuarioId = usuarioIdStr ? parseInt(usuarioIdStr) : user?.id;

      if (!sessionId || !plan || !usuarioId) {
        setError('Datos de sesión incompletos.');
        setLoading(false);
        return;
      }

      try {
        let nombre = 'Aventurero';
        if (plan === 'PREMIUM') nombre = 'Héroe';
        if (plan === 'VIP') nombre = 'Dungeon Master';

        await createSuscripcion({
          usuarioId,
          nombre,
          tipo: plan
        });

        // Esperar unos segundos y redirigir al perfil
        setTimeout(() => {
          navigate('/profile');
        }, 3000);
      } catch (e: any) {
        console.error(e);
        setError('Ocurrió un error al procesar tu suscripción. Contacta soporte.');
      } finally {
        setLoading(false);
      }
    };

    processPayment();
  }, [searchParams, user, navigate]);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', padding: '20px', color: 'white', background: '#0a0a0a' }}>
      <img src="/images/RavenLoft-logo (2).png" alt="Ravenloft Castle" style={{ width: '200px', marginBottom: '30px' }} />
      {loading ? (
        <h2>Procesando tu pago mágico...</h2>
      ) : error ? (
        <div style={{ textAlign: 'center' }}>
          <h2 style={{ color: '#e74c3c' }}>Error</h2>
          <p>{error}</p>
          <button onClick={() => navigate('/subscription')} style={{ marginTop: '20px', padding: '10px 20px', background: '#742514', border: 'none', color: 'white', cursor: 'pointer', borderRadius: '4px' }}>
            Volver
          </button>
        </div>
      ) : (
        <div style={{ textAlign: 'center' }}>
          <h2 style={{ color: '#2ecc71' }}>¡Pago Exitoso!</h2>
          <p>Tu suscripción se ha aplicado correctamente. Preparando tu nueva aventura...</p>
        </div>
      )}
    </div>
  );
}

import './Subscription.css';
import { useNavigate } from 'react-router-dom';
import { Crown, Sparkles, Sword } from 'lucide-react';
import { useAuth } from '../../services/AuthContext';
import { createSuscripcion, getUserSuscripciones } from '../../services/suscripcionService';
import { useState, useEffect } from 'react';
import { ModalAlert } from '../../components/ModalAlert/ModalAlert';

export function Subscription() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [activeSubscription, setActiveSubscription] = useState<any>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalConfig, setModalConfig] = useState<{ message: string; title: string; }>({ message: '', title: '' });

  useEffect(() => {
    if (user?.id) {
      getUserSuscripciones(user.id)
        .then((suscripciones) => {
          const active = suscripciones.find(s => s.estado === 'ACTIVA');
          setActiveSubscription(active || null);
        })
        .catch(err => console.error("Error al comprobar suscripciones", err));
    }
  }, [user?.id]);

  const handleSelectPlan = async (nombrePlan: string, tipo: 'BASICA' | 'PREMIUM' | 'VIP') => {
    if (!user) {
      navigate('/login');
      return;
    }

    try {
      await createSuscripcion({
        usuarioId: user.id,
        nombre: nombrePlan,
        tipo
      });
      navigate('/profile');
    } catch (e: any) {
      console.error(e);
      let errorMsg = 'Error al elegir tu suscripción. Inténtalo más tarde.';
      try {
        const errObj = JSON.parse(e.message);
        if (errObj.mensaje) errorMsg = errObj.mensaje;
      } catch {
        if (e.message && !e.message.startsWith('Error al')) {
           errorMsg = e.message;
        }
      }
      setModalConfig({ title: '¡Atención!', message: errorMsg });
      setIsModalOpen(true);
    }
  };

  return (
    <div className="subscription-container">
      <div className="subscription-header">
        <img src="/images/RavenLoft-logo (2).png" alt="Ravenloft Castle" className="subscription-logo" />
        <h1 className="subscription-title">Forja tu Leyenda</h1>
        <p className="subscription-subtitle">Elige el camino de tu aventura y desbloquea todo el potencial de tu campaña.</p>
      </div>

      <div className="plans-grid">
        {/* Plan Aventurero */}
        <div className="plan-card">
          <div className="plan-header">
            <Sword className="plan-icon" size={32} />
            <h2>Aventurero</h2>
            <div className="plan-price">
              <span className="amount">Gratis</span>
            </div>
            <p className="plan-desc">Lo esencial para comenzar tu viaje.</p>
          </div>
          <ul className="plan-features">
            <li>Creación de 3 personajes</li>
            <li>Acceso a campañas públicas</li>
            <li>Ficha básica de personaje</li>
            <li>Dado virtual estándar</li>
          </ul>
          <button
            className="plan-btn"
            onClick={() => handleSelectPlan('Aventurero', 'BASICA')}
            disabled={activeSubscription?.tipo === 'BASICA'}
            style={activeSubscription?.tipo === 'BASICA' ? { opacity: 0.5, cursor: 'not-allowed' } : {}}
          >
            {activeSubscription?.tipo === 'BASICA' ? 'Plan Actual' : 'Comenzar'}
          </button>
        </div>

        {/* Plan Héroe (Featured) */}
        <div className="plan-card featured">
          <div className="plan-badge">Más Popular</div>
          <div className="plan-header">
            <Sparkles className="plan-icon" size={32} />
            <h2>Héroe</h2>
            <div className="plan-price">
              <span className="currency">€</span>
              <span className="amount">4.99</span>
              <span className="period">/mes</span>
            </div>
            <p className="plan-desc">Para aventureros dedicados.</p>
          </div>
          <ul className="plan-features">
            <li>Creación ilimitada de personajes</li>
            <li>Mapas interactivos básicos</li>
            <li>Diario de campaña avanzado</li>
            <li>Dados virtuales personalizados</li>
          </ul>
          <button
            className="plan-btn featured-btn"
            onClick={() => handleSelectPlan('Héroe', 'PREMIUM')}
            disabled={activeSubscription?.tipo === 'PREMIUM'}
            style={activeSubscription?.tipo === 'PREMIUM' ? { opacity: 0.5, cursor: 'not-allowed' } : {}}
          >
            {activeSubscription?.tipo === 'PREMIUM' ? 'Plan Actual' : 'Elegir Héroe'}
          </button>
        </div>

        {/* Plan Dungeon Master */}
        <div className="plan-card">
          <div className="plan-header">
            <Crown className="plan-icon" size={32} />
            <h2>Dungeon Master</h2>
            <div className="plan-price">
              <span className="currency">€</span>
              <span className="amount">9.99</span>
              <span className="period">/mes</span>
            </div>
            <p className="plan-desc">Todo el poder para crear mundos.</p>
          </div>
          <ul className="plan-features">
            <li>Todo el contenido del plan Héroe</li>
            <li>Creación ilimitada de campañas</li>
          </ul>
          <button
            className="plan-btn"
            onClick={() => handleSelectPlan('Dungeon Master', 'VIP')}
            disabled={activeSubscription?.tipo === 'VIP'}
            style={activeSubscription?.tipo === 'VIP' ? { opacity: 0.5, cursor: 'not-allowed' } : {}}
          >
            {activeSubscription?.tipo === 'VIP' ? 'Plan Actual' : 'Elegir DM'}
          </button>
        </div>
      </div>

      <ModalAlert
        isOpen={isModalOpen}
        title={modalConfig.title}
        message={modalConfig.message}
        confirmText="Aceptar"
        onConfirm={() => setIsModalOpen(false)}
        showImage={false}
      />
    </div>
  );
}

import './Subscription.css';
import { useNavigate } from 'react-router-dom';
import { Crown, Sparkles, Sword } from 'lucide-react';
import { useAuth } from '../../services/AuthContext';
import { createSuscripcion, getUserSuscripciones, createStripeCheckoutSession } from '../../services/suscripcionService';
import { useState, useEffect } from 'react';
import { ModalAlert } from '../../components/ModalAlert/ModalAlert';

export function Subscription() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [activeSubscription, setActiveSubscription] = useState<any>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalConfig, setModalConfig] = useState<{ message: string; title: string; }>({ message: '', title: '' });

  useEffect(() => {
    if (user?.id) {
      getUserSuscripciones(user.id)
        .then((suscripciones) => {
          const active = suscripciones.find(s => s.estado === 'ACTIVA');
          setActiveSubscription(active || null);
        })
        .catch(err => console.error("Error al comprobar suscripciones", err));
    }
  }, [user?.id]);

  const handleSelectPlan = async (nombrePlan: string, tipo: 'BASICA' | 'PREMIUM' | 'VIP') => {
    if (!user) {
      navigate('/login');
      return;
    }

    try {
      // Si el plan es BÁSICO (Gratis), no pasamos por Stripe
      if (tipo === 'BASICA') {
        await createSuscripcion({
          usuarioId: user.id,
          nombre: nombrePlan,
          tipo
        });
        navigate('/profile');
        return;
      }

      // Si es de pago (Héroe o DM), creamos la sesión en Stripe
      const response = await createStripeCheckoutSession(tipo, user.id);
      if (response && response.url) {
        window.location.href = response.url;
      } else {
        throw new Error('No se pudo obtener la URL de pago.');
      }
    } catch (e: any) {
      console.error(e);
      let errorMsg = 'Error al redirigir al pago. Inténtalo más tarde.';
      try {
        const errObj = JSON.parse(e.message);
        if (errObj.mensaje) errorMsg = errObj.mensaje;
      } catch {
        if (e.message && !e.message.startsWith('Error al')) {
           errorMsg = e.message;
        }
      }
      setModalConfig({ title: '¡Atención!', message: errorMsg });
      setIsModalOpen(true);
    }
  };

  return (
    <div className="subscription-container">
      <div className="subscription-header">
        <img src="/images/RavenLoft-logo (2).png" alt="Ravenloft Castle" className="subscription-logo" />
        <h1 className="subscription-title">Forja tu Leyenda</h1>
        <p className="subscription-subtitle">Elige el camino de tu aventura y desbloquea todo el potencial de tu campaña.</p>
      </div>

      <div className="plans-grid">
        {/* Plan Aventurero */}
        <div className="plan-card">
          <div className="plan-header">
            <Sword className="plan-icon" size={32} />
            <h2>Aventurero</h2>
            <div className="plan-price">
              <span className="amount">Gratis</span>
            </div>
            <p className="plan-desc">Lo esencial para comenzar tu viaje.</p>
          </div>
          <ul className="plan-features">
            <li>Creación de 3 personajes</li>
            <li>Acceso a campañas públicas</li>
            <li>Ficha básica de personaje</li>
            <li>Dado virtual estándar</li>
          </ul>
          <button
            className="plan-btn"
            onClick={() => handleSelectPlan('Aventurero', 'BASICA')}
            disabled={activeSubscription?.tipo === 'BASICA'}
            style={activeSubscription?.tipo === 'BASICA' ? { opacity: 0.5, cursor: 'not-allowed' } : {}}
          >
            {activeSubscription?.tipo === 'BASICA' ? 'Plan Actual' : 'Comenzar'}
          </button>
        </div>

        {/* Plan Héroe (Featured) */}
        <div className="plan-card featured">
          <div className="plan-badge">Más Popular</div>
          <div className="plan-header">
            <Sparkles className="plan-icon" size={32} />
            <h2>Héroe</h2>
            <div className="plan-price">
              <span className="currency">€</span>
              <span className="amount">4.99</span>
              <span className="period">/mes</span>
            </div>
            <p className="plan-desc">Para aventureros dedicados.</p>
          </div>
          <ul className="plan-features">
            <li>Creación ilimitada de personajes</li>
            <li>Mapas interactivos básicos</li>
            <li>Diario de campaña avanzado</li>
            <li>Dados virtuales personalizados</li>
          </ul>
          <button
            className="plan-btn featured-btn"
            onClick={() => handleSelectPlan('Héroe', 'PREMIUM')}
            disabled={activeSubscription?.tipo === 'PREMIUM'}
            style={activeSubscription?.tipo === 'PREMIUM' ? { opacity: 0.5, cursor: 'not-allowed' } : {}}
          >
            {activeSubscription?.tipo === 'PREMIUM' ? 'Plan Actual' : 'Elegir Héroe'}
          </button>
        </div>

        {/* Plan Dungeon Master */}
        <div className="plan-card">
          <div className="plan-header">
            <Crown className="plan-icon" size={32} />
            <h2>Dungeon Master</h2>
            <div className="plan-price">
              <span className="currency">€</span>
              <span className="amount">9.99</span>
              <span className="period">/mes</span>
            </div>
            <p className="plan-desc">Todo el poder para crear mundos.</p>
          </div>
          <ul className="plan-features">
            <li>Todo el contenido del plan Héroe</li>
            <li>Creación ilimitada de campañas</li>
          </ul>
          <button
            className="plan-btn"
            onClick={() => handleSelectPlan('Dungeon Master', 'VIP')}
            disabled={activeSubscription?.tipo === 'VIP'}
            style={activeSubscription?.tipo === 'VIP' ? { opacity: 0.5, cursor: 'not-allowed' } : {}}
          >
            {activeSubscription?.tipo === 'VIP' ? 'Plan Actual' : 'Elegir DM'}
          </button>
        </div>
      </div>

      <ModalAlert
        isOpen={isModalOpen}
        title={modalConfig.title}
        message={modalConfig.message}
        confirmText="Aceptar"
        onConfirm={() => setIsModalOpen(false)}
        showImage={false}
      />
    </div>
  );
}

import { API_URL, authHeaders, fetchWithAuth } from './api';

export interface SuscripcionDTO {
  id: number;
  usuarioId: number;
  nombre: string;
  tipo: 'BASICA' | 'PREMIUM' | 'VIP';
  estado: string;
  fechaAlta: string;
  fechaBaja?: string;
}

export interface SuscripcionCreateDTO {
  usuarioId: number;
  nombre: string;
  tipo: 'BASICA' | 'PREMIUM' | 'VIP';
}

export const createSuscripcion = async (dto: SuscripcionCreateDTO): Promise<SuscripcionDTO> => {
  const response = await fetchWithAuth(`${API_URL}/api/suscripciones`, {
    method: 'POST',
    headers: authHeaders(),
    body: JSON.stringify(dto),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(errorText || 'Error al crear la suscripción');
  }

  return response.json();
};

export const getUserSuscripciones = async (usuarioId: number): Promise<SuscripcionDTO[]> => {
  const response = await fetchWithAuth(`${API_URL}/api/suscripciones/usuario/${usuarioId}`, {
    method: 'GET',
    headers: authHeaders(),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(errorText || 'Error al obtener las suscripciones del usuario');
  }

  return response.json();
};

export const getMySuscripciones = async (): Promise<SuscripcionDTO[]> => {
  const response = await fetchWithAuth(`${API_URL}/api/suscripciones`, {
    method: 'GET',
    headers: authHeaders(),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(errorText || 'Error al obtener tus suscripciones');
  }

  return response.json();
};

export const cancelarSuscripcion = async (id: number): Promise<void> => {
  const response = await fetchWithAuth(`${API_URL}/api/suscripciones/${id}/cancelar`, {
    method: 'PUT',
    headers: authHeaders(),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(errorText || 'Error al cancelar la suscripción');
  }
};

